mapper.update:
update law_file
set case_id = #{caseId,jdbcType=BIGINT},
  case_no = #{caseNo,jdbcType=VARCHAR},
  file_type = #{fileType,jdbcType=INTEGER},
  file_id = #{fileId,jdbcType=BIGINT}
where id = #{id,jdbcType=BIGINT}

mapper.select:
select lf.id as id, lf.case_id as caseId, lf.case_no as caseNo, lf.file_type as fileType, lf.file_id as fileId from law_file lf where lf.case_id = #{caseId,jdbcType=BIGINT}
and lf.file_type = #{fileType,jdbcType=BIGINT}
and lf.file_type = 1
order by id desc

SELECT a.id,b.file_path filePath,b.create_time createTime,DATE_FORMAT(b.create_time,'%Y-%m-%d %H:%i') as createTimeName
from law_file a LEFT JOIN
common_file b on a.file_id = b.id
WHERE a.case_id=#{caseId,jdbcType=BIGINT}

    and a.file_type = #{fileType,jdbcType=BIGINT}

order by b.create_time desc
